// Module 08 end-to-end tests: backgrounds and layout, the camera bubble, music with volume and
// fades, subtitles (manual and generated by the local speech engine), text and logo watermarks,
// custom output size, everything surviving a reload, and all of it in the exported video.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { existsSync, mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { makeWav } from '../fixtures/makePdf.mjs';
import { button, dialogButton, openPanel, readRecordings, seekEditor, sleep, waitForText, startExport, waitSaved } from './lib.mjs';

function readProject(page, projectId) {
  return page.evaluate(async (id) => {
    const request = indexedDB.open('zoomcapture');
    const db = await new Promise((r) => (request.onsuccess = () => r(request.result)));
    const project = await new Promise((r) => {
      const q = db.transaction('projects').objectStore('projects').get(id);
      q.onsuccess = () => r(q.result);
    });
    db.close();
    return project;
  }, projectId);
}

/** Colour of the preview canvas at a point (fractions of its size), after the frame at `ms`. */
async function previewPixel(editor, ms, x, y) {
  await seekEditor(editor, ms);
  return editor.evaluate(
    async (x, y) => {
      for (let i = 0; i < 4; i++) await new Promise((r) => requestAnimationFrame(r));
      const canvas = document.querySelector('[data-testid=zoom-canvas]');
      return Array.from(canvas.getContext('2d').getImageData(Math.round(canvas.width * x), Math.round(canvas.height * y), 1, 1).data.slice(0, 3));
    },
    x,
    y,
  );
}
/** Pixels of the preview canvas along a line (fractions of its size), after the frame at `ms`. */
async function previewLine(editor, ms, from, to, steps = 60) {
  await seekEditor(editor, ms);
  return editor.evaluate(
    async (from, to, steps) => {
      for (let i = 0; i < 4; i++) await new Promise((r) => requestAnimationFrame(r));
      const canvas = document.querySelector('[data-testid=zoom-canvas]');
      const ctx = canvas.getContext('2d');
      return Array.from({ length: steps + 1 }, (_, i) => {
        const x = from[0] + ((to[0] - from[0]) * i) / steps;
        const y = from[1] + ((to[1] - from[1]) * i) / steps;
        return Array.from(ctx.getImageData(Math.round((canvas.width - 1) * x), Math.round((canvas.height - 1) * y), 1, 1).data.slice(0, 3));
      });
    },
    from,
    to,
    steps,
  );
}
/** How many points differ between two lines of pixels. */
const differing = (a, b) => a.filter((pixel, index) => !near(pixel, b[index], 30)).length;
const near = (actual, expected, tolerance = 40) => actual.every((value, index) => Math.abs(value - expected[index]) <= tolerance);

/** Sets a colour input the way picking a colour does (React listens to `input`). */
async function setColour(editor, xpath, value) {
  const input = await editor.waitForSelector(`xpath/${xpath}`);
  await input.evaluate((element, value) => {
    const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
    setter.call(element, value);
    element.dispatchEvent(new Event('input', { bubbles: true }));
  }, value);
}

/** Types into a text field, replacing what is there. */
async function replaceText(editor, handle, text) {
  await handle.click();
  await handle.evaluate((element) => element.select());
  await editor.keyboard.type(text);
}

/** A spoken sentence from Windows text-to-speech (null elsewhere). */
function speechWav(dir) {
  if (process.platform !== 'win32') return null;
  const path = join(dir, 'speech.wav');
  execFileSync('powershell', [
    '-NoProfile',
    '-Command',
    `Add-Type -AssemblyName System.Speech; $s = New-Object System.Speech.Synthesis.SpeechSynthesizer; $s.Rate = -1; $s.SetOutputToWaveFile('${path}'); $s.Speak('Hello and welcome. Today we will add subtitles automatically.'); $s.Dispose()`,
  ]);
  return existsSync(path) ? path : null;
}

export async function runModule08(test, getEnv, relaunch) {
  const state = {};
  const dir = mkdtempSync(join(tmpdir(), 'zc-m08-'));
  const musicPath = join(dir, 'Music.wav');
  writeFileSync(musicPath, makeWav(5));

  await test('module 08 setup: a recording with a camera', async () => {
    await relaunch();
    const env = getEnv();
    await env.worker.evaluate(async () => {
      const { settings } = await chrome.storage.local.get('settings');
      await chrome.storage.local.set({ settings: { ...settings, defaultSource: 'screen', cameraEnabled: false, microphoneEnabled: true, countdownSeconds: 0, floatingControls: false } });
    });
    const popup = await env.open('popup/index.html');
    const existing = new Set(env.browser.targets());
    const studioTarget = env.browser.waitForTarget((t) => t.url().includes('/recording/index.html') && !existing.has(t));
    await (await button(popup, 'Start Recording')).click();
    const studio = await (await studioTarget).page();
    await studio.bringToFront();
    // A steady drawn camera (Chrome's fake camera stops at random in automation).
    await studio.evaluate(() => {
      const original = navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices);
      navigator.mediaDevices.getUserMedia = async (constraints) => {
        if (!constraints?.video) return original(constraints);
        const canvas = Object.assign(document.createElement('canvas'), { width: 640, height: 480 });
        const ctx = canvas.getContext('2d');
        setInterval(() => {
          ctx.fillStyle = '#d0b090';
          ctx.fillRect(0, 0, 640, 480);
        }, 33);
        return canvas.captureStream(30);
      };
    });
    await (await button(studio, 'Choose screen')).click();
    await studio.waitForSelector('video[aria-label="Live preview of the shared surface"]');
    await (await studio.waitForSelector('xpath/.//*[@role="switch"][contains(., "Camera")]')).click();
    await studio.waitForSelector('[data-testid=camera-bubble]');
    await (await button(studio, 'Start recording')).click();
    await studio.waitForSelector('[role=timer]');
    await sleep(5000);
    await (await button(studio, 'Stop')).click();
    await studio.waitForSelector('xpath/.//h1[contains(., "Recording saved")]', { timeout: 30_000 });
    const recording = (await readRecordings(studio)).sort((a, b) => b.createdAt - a.createdAt)[0];
    await studio.close();
    const editor = await env.open(`editor/index.html?recording=${recording.id}`);
    await editor.setViewport({ width: 1440, height: 900 });
    await editor.bringToFront();
    await editor.waitForSelector('[data-testid=preview-stage] video');
    Object.assign(state, { editor, recording });
  });

  await test('module 08 background: colour behind a floating recording, in the preview', async () => {
    const { editor } = state;
    await openPanel(editor, 'Canvas');
    await (await editor.waitForSelector('xpath/.//button[@role="radio"][normalize-space()="Colour"]')).click();
    await setColour(editor, './/*[@data-testid="background-panel"]//label[normalize-space()="Colour"]/following-sibling::input', '#2040ff');
    await (await editor.waitForSelector('xpath/.//button[normalize-space()="Floating"]')).click();
    await waitSaved(editor);
    // The frame's corner shows the background; the middle shows the recording.
    assert.ok(near(await previewPixel(editor, 1000, 0.01, 0.01), [32, 64, 255]), 'background in the corner');
    assert.ok(!near(await previewPixel(editor, 1000, 0.5, 0.5), [32, 64, 255]), 'recording in the middle');
    // A preset and the gradient work too (then back to the colour for the checks below).
    await (await editor.waitForSelector('xpath/.//button[@role="radio"][normalize-space()="Presets"]')).click();
    await (await editor.waitForSelector('button[aria-label="Sunset"]')).click();
    assert.ok(!near(await previewPixel(editor, 1000, 0.01, 0.01), [32, 64, 255]), 'preset drawn');
    await (await editor.waitForSelector('xpath/.//button[@role="radio"][normalize-space()="Colour"]')).click();
    await waitSaved(editor);
    const project = await readProject(editor, state.recording.projectId);
    assert.equal(project.background.kind, 'color');
    assert.equal(project.background.color, '#2040ff');
    assert.deepEqual(project.frameLayout, { padding: 0.1, radius: 0.04, shadow: 0.8 });
  });

  await test('module 08 camera: rounded with a ring, moved in the preview, kept in the frame', async () => {
    const { editor } = state;
    await openPanel(editor, 'Camera');
    await (await editor.waitForSelector('xpath/.//button[@role="radio"][contains(., "Rounded")]')).click();
    await (await editor.waitForSelector('xpath/.//*[@role="switch"][contains(., "Background ring")]')).click();
    await setColour(editor, './/*[@data-testid="camera-panel"]//label[normalize-space()="Ring colour"]/following-sibling::input', '#ff8800');
    // Drag the bubble far past the top-left corner: it stops inside the frame.
    const handle = await (await editor.waitForSelector('[data-testid=camera-handle]')).boundingBox();
    await editor.mouse.move(handle.x + handle.width / 2, handle.y + handle.height / 2);
    await editor.mouse.down();
    await editor.mouse.move(handle.x - 2000, handle.y - 2000, { steps: 6 });
    await editor.mouse.up();
    await waitSaved(editor);
    const layout = (await readProject(editor, state.recording.projectId)).cameraLayout;
    assert.equal(layout.shape, 'rounded');
    assert.equal(layout.background, '#ff8800');
    const width = layout.scale;
    assert.ok(Math.abs(layout.x - width / 2) < 0.002, `left edge at the frame's edge: ${JSON.stringify(layout)}`);
    // Drawn there: a line across the bubble's middle crosses the ring colour.
    const aspect = await editor.$eval('[data-testid=zoom-canvas]', (canvas) => canvas.width / canvas.height);
    const middle = ((width * 0.75) / 2) * aspect;
    const line = await previewLine(editor, 1000, [0, middle], [width, middle]);
    assert.ok(line.some((pixel) => near(pixel, [255, 136, 0], 60)), `ring drawn: ${JSON.stringify(line.slice(0, 8))}`);
  });

  await test('module 08 subtitles: generated by the local speech engine, then corrected', async () => {
    const { editor, recording } = state;
    const speech = speechWav(dir);
    if (!speech) return console.log('    (skipped: needs Windows text-to-speech for a spoken test sentence)');
    // The speech goes on its own track (imported as music, the quickest way to place it at 0).
    await openPanel(editor, 'Audio');
    await (await editor.waitForSelector('input[data-testid=music-upload]')).uploadFile(speech);
    await editor.waitForSelector('ul[aria-label="Music clips"] li');
    await waitSaved(editor);
    const speechTrack = (await readProject(editor, recording.projectId)).timeline.tracks.find((track) => track.kind === 'music');
    await openPanel(editor, 'Captions');
    // Transcribe only that track.
    const labels = await editor.$$eval('[data-testid=captions-panel] fieldset label', (items) => items.map((item) => item.textContent));
    const boxes = await editor.$$('[data-testid=captions-panel] fieldset input[type=checkbox]');
    for (let i = 0; i < boxes.length; i++) {
      const want = labels[i] === speechTrack.name;
      if ((await boxes[i].evaluate((box) => box.checked)) !== want) await boxes[i].click();
    }
    await (await button(editor, 'Generate subtitles')).click();
    await editor.waitForFunction(() => /subtitles generated|not generated|No speech/.test(document.body.innerText), { timeout: 600_000 });
    await waitForText(editor, 'subtitles generated');
    await waitSaved(editor);
    let cues = (await readProject(editor, recording.projectId)).subtitles[0].cues;
    const words = cues.map((cue) => cue.text).join(' ').toLowerCase();
    assert.ok(words.includes('welcome') && words.includes('subtitles'), `recognised: ${words}`);
    // Reviewed and corrected like any subtitle.
    const first = await editor.waitForSelector('[data-testid=captions-panel] ul[aria-label="Subtitles"] textarea');
    await replaceText(editor, first, 'Hello and welcome (corrected).');
    await waitSaved(editor);
    cues = (await readProject(editor, recording.projectId)).subtitles[0].cues;
    assert.equal(cues[0].text, 'Hello and welcome (corrected).');
    // Cleared, with the speech, for the tests below.
    while (await editor.$('button[aria-label="Delete subtitle"]')) {
      await (await editor.$('button[aria-label="Delete subtitle"]')).click();
      await sleep(50);
    }
    await openPanel(editor, 'Audio');
    await (await editor.waitForSelector('button[aria-label="Remove speech.wav from the timeline"]')).click();
    await editor.waitForFunction(() => !document.querySelector('ul[aria-label="Music clips"]'));
    await waitSaved(editor);
    assert.equal((await readProject(editor, recording.projectId)).subtitles[0]?.cues.length ?? 0, 0);
  });

  await test('module 08 music: added under the recording with volume and fades, previewed together', async () => {
    const { editor } = state;
    await openPanel(editor, 'Audio');
    await (await editor.waitForSelector('input[data-testid=music-upload]')).uploadFile(musicPath);
    await editor.waitForSelector('ul[aria-label="Music clips"] li');
    const fadeIn = await editor.waitForSelector('xpath/.//ul[@aria-label="Music clips"]//label[contains(., "Fade in")]/following-sibling::div/input');
    await replaceText(editor, fadeIn, '2');
    await editor.keyboard.press('Enter');
    await waitSaved(editor);
    let project = await readProject(editor, state.recording.projectId);
    const musicTrack = project.timeline.tracks.find((track) => track.kind === 'music');
    const music = musicTrack.clips[0];
    assert.equal(music.startMs, 0);
    assert.equal(music.fadeInMs, 2000);
    // Separate volumes: the music track at 50 %.
    await editor.evaluate(() => {
      const slider = [...document.querySelectorAll('ul[aria-label="Audio sources"] input[type=range]')].at(-1);
      const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
      setter.call(slider, '0.5');
      slider.dispatchEvent(new Event('input', { bubbles: true }));
    });
    await waitSaved(editor);
    project = await readProject(editor, state.recording.projectId);
    assert.equal(project.timeline.tracks.find((track) => track.id === musicTrack.id).volume, 0.5);
    // The preview plays it with the recording, at volume × fade: half-way into the fade-in, 25 %.
    await seekEditor(editor, 1000);
    const volume = await editor.$eval(`[data-testid=preview-stage] audio[data-track="${musicTrack.id}"]`, (audio) => audio.volume);
    assert.ok(Math.abs(volume - 0.25) < 0.02, `volume ${volume}`);
    await seekEditor(editor, 3000);
    assert.ok(Math.abs((await editor.$eval(`[data-testid=preview-stage] audio[data-track="${musicTrack.id}"]`, (audio) => audio.volume)) - 0.5) < 0.02);
    state.musicTrackId = musicTrack.id;
  });

  await test('module 08 subtitles: added by hand, styled, shown in the preview and on the timeline', async () => {
    const { editor } = state;
    await openPanel(editor, 'Captions');
    await seekEditor(editor, 1000);
    await (await button(editor, 'Add at playhead')).click();
    const area = await editor.waitForSelector('[data-testid=captions-panel] ul[aria-label="Subtitles"] textarea');
    await replaceText(editor, area, 'Hello subtitles');
    await editor.keyboard.down('Shift');
    await editor.keyboard.press('Enter');
    await editor.keyboard.up('Shift');
    await editor.keyboard.type('second line');
    await (await editor.waitForSelector('xpath/.//*[@data-testid="captions-panel"]//button[@role="radio"][normalize-space()="Top"]')).click();
    await waitSaved(editor);
    const project = await readProject(editor, state.recording.projectId);
    const cue = project.subtitles[0].cues[0];
    assert.deepEqual([cue.startMs, cue.endMs, cue.text], [1000, 3500, 'Hello subtitles\nsecond line']);
    assert.equal(project.subtitleStyle.position, 'top');
    await editor.waitForSelector('[data-testid=captions-track] button');
    // Drawn at the top: the frame's top band differs while the cue is on, compared with after it.
    const during = await previewLine(editor, 2000, [0.5, 0], [0.5, 0.25]);
    const after = await previewLine(editor, 4000, [0.5, 0], [0.5, 0.25]);
    assert.ok(differing(during, after) > 3, 'subtitle drawn at the top');
  });

  await test('module 08 overlays: text and logo watermarks, a callout, all previewed', async () => {
    const { editor, recording } = state;
    await openPanel(editor, 'Text');
    await (await button(editor, 'Add callout')).click();
    await openPanel(editor, 'Text');
    await replaceText(editor, await editor.waitForSelector('input[aria-label="Watermark text"]'), '© ZoomCapture test');
    await (await editor.waitForSelector('xpath/.//*[@data-testid="overlays-panel"]//button[normalize-space()="Add"]')).click();
    // A logo made in the page (orange square), uploaded and placed bottom right.
    const png = await editor.evaluate(async () => {
      const canvas = new OffscreenCanvas(200, 200);
      const ctx = canvas.getContext('2d');
      ctx.fillStyle = '#ff6600';
      ctx.fillRect(0, 0, 200, 200);
      return Array.from(new Uint8Array(await (await canvas.convertToBlob({ type: 'image/png' })).arrayBuffer()));
    });
    const logoPath = join(dir, 'logo.png');
    writeFileSync(logoPath, Buffer.from(png));
    await openPanel(editor, 'Text');
    await (await editor.waitForSelector('input[data-testid=logo-upload]')).uploadFile(logoPath);
    await waitForText(editor, 'Imported “logo.png”');
    await waitSaved(editor);
    const project = await readProject(editor, recording.projectId);
    const clips = project.timeline.tracks.flatMap((track) => track.clips.map((clip) => ({ ...clip, kind: track.kind })));
    const watermark = clips.find((clip) => clip.type === 'text' && clip.text === '© ZoomCapture test');
    assert.ok(watermark && watermark.style.opacity === 0.6 && watermark.startMs === 0, `text watermark ${JSON.stringify(watermark)}`);
    assert.ok(clips.some((clip) => clip.type === 'text' && clip.callout), 'callout');
    const logo = clips.find((clip) => clip.type === 'media' && clip.transform && clip.opacity === 0.85);
    assert.ok(logo && logo.transform.x > 0.8 && logo.transform.y > 0.6, `logo bottom right: ${JSON.stringify(logo?.transform)}`);
    // The logo is drawn there (blended at 85 %, orange-ish).
    const pixel = await previewPixel(editor, 2000, 0.1 + 0.8 * (logo.transform.x + logo.transform.width / 2), 0.1 + 0.8 * (logo.transform.y + 0.05));
    assert.ok(pixel[0] > 180 && pixel[1] > 60 && pixel[1] < 160 && pixel[2] < 90, `logo drawn: ${pixel}`);
  });

  await test('module 08 custom size: the preview takes the new shape, everything keeps its place', async () => {
    const { editor, recording } = state;
    await openPanel(editor, 'Canvas');
    await (await editor.waitForSelector('xpath/.//button[@role="radio"][normalize-space()="Custom"]')).click();
    await (await editor.waitForSelector('xpath/.//button[contains(., "1080×1350")]')).click();
    await waitSaved(editor);
    const project = await readProject(editor, recording.projectId);
    assert.equal(project.aspectRatio, 'custom');
    assert.deepEqual(project.customSize, { width: 1080, height: 1350 });
    const box = await (await editor.$('[data-testid=zoom-canvas]')).boundingBox();
    assert.ok(Math.abs(box.width / box.height - 0.8) < 0.01, `preview ${box.width}×${box.height}`);
    // The background still fills the frame around the recording.
    assert.ok(near(await previewPixel(editor, 1000, 0.5, 0.02), [32, 64, 255]), 'background above the recording');
  });

  await test('module 08 reopening: every effect is still there after reloading', async () => {
    const { editor, recording } = state;
    const before = await readProject(editor, recording.projectId);
    await editor.reload();
    await editor.waitForSelector('[data-testid=preview-stage] video');
    const after = await readProject(editor, recording.projectId);
    for (const key of ['aspectRatio', 'customSize', 'background', 'frameLayout', 'cameraLayout', 'subtitleStyle', 'subtitles', 'timeline']) {
      assert.deepEqual(after[key], before[key], key);
    }
    assert.ok(near(await previewPixel(editor, 1000, 0.5, 0.02), [32, 64, 255]), 'background drawn after reopening');
    await openPanel(editor, 'Captions');
    await editor.waitForFunction(() => [...document.querySelectorAll('[data-testid=captions-panel] textarea')].some((area) => area.value === 'Hello subtitles\nsecond line'));
  });

  await test('module 08 export: background, camera, subtitles, overlays and music in the video', async () => {
    const { editor } = state;
    await (await button(editor, 'Export video')).click();
    await startExport(editor);
    await editor.waitForSelector('[data-testid=rendered-video]', { timeout: 180_000 });
    await editor.waitForFunction(() => document.querySelector('[data-testid=rendered-video]').readyState >= 1);
    const summary = await editor.$eval('[data-testid=render-summary]', (p) => p.textContent);
    assert.match(summary, /1080×1350/, summary);
    assert.match(summary, /audio mixed/, summary);
    const lineAt = (t, x, y0, y1) =>
      editor.evaluate(
        async (t, x, y0, y1) => {
          const video = document.querySelector('[data-testid=rendered-video]');
          video.pause();
          await new Promise((resolve) => {
            video.addEventListener('seeked', resolve, { once: true });
            video.currentTime = t;
          });
          // Chrome paints an H.264 frame a moment after 'seeked': wait for it.
          await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
          const canvas = new OffscreenCanvas(video.videoWidth, video.videoHeight);
          const ctx = canvas.getContext('2d');
          ctx.drawImage(video, 0, 0);
          return Array.from({ length: 61 }, (_, i) => {
            const y = y0 + ((y1 - y0) * i) / 60;
            return Array.from(ctx.getImageData(Math.round((canvas.width - 1) * x), Math.round((canvas.height - 1) * y), 1, 1).data.slice(0, 3));
          });
        },
        t,
        x,
        y0,
        y1,
      );
    { const bg = (await lineAt(1, 0.5, 0.02, 0.02))[0]; assert.ok(near(bg, [32, 64, 255], 50), `background in the video: ${bg}`); }
    // The subtitle (top) is in the video while its cue is on, not after it.
    const during = await lineAt(2, 0.5, 0, 0.25);
    const later = await lineAt(4.2, 0.5, 0, 0.25);
    assert.ok(differing(during, later) > 3, 'subtitle in the video');
    await (await dialogButton(editor, 'Close')).click();
  });
}
